--
-- Table structure for table `ml_incremental_training_queue_tbl`
--

DROP TABLE IF EXISTS `ml_incremental_training_queue_tbl`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ml_incremental_training_queue_tbl` (
  `queue_id` int NOT NULL AUTO_INCREMENT,
  `file_upload_id` int DEFAULT NULL COMMENT 'Reference to uploaded file',
  `training_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Extracted text for training',
  `confirmed_category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'User-confirmed category',
  `prediction_confidence` decimal(5,2) DEFAULT NULL,
  `status` enum('pending','processed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `processed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`queue_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_file_upload` (`file_upload_id`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Queues training samples for incremental ML learning';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ml_incremental_training_queue_tbl`
--

LOCK TABLES `ml_incremental_training_queue_tbl` WRITE;
/*!40000 ALTER TABLE `ml_incremental_training_queue_tbl` DISABLE KEYS */;
INSERT INTO `ml_incremental_training_queue_tbl` VALUES (1,27,'OFFICE OF THE STUDENT AFFAIRS AND SERVICES UNIVERSITY OF ANTIQUE STUDENT GOVERNMENT tlmc.usg@antiquespride.edu.ph ACTIVITY DESIGN Title: TO CONDUCT ACQUAINTED CHRISTMAS PARTY CELEBRATION IN THE UNIVERSITY OF    ANTIQUE-TARIO LIM MEMORIAL CAMPUS Venue: At UATLMC Bandoja Center  Date: December 18, 2024 Source of Income: UASG   Rationale: University of Antique Student Government (UASG) is recognized as the mother of all organizations that serves as the link between the university administration and the student body which strengthen its solidarity, camaraderie and promote its total development to serve the students and the community that is created to provide students the experience and training in the democratic form of government, voice for the student body, give students opportunity to develop effective and dynamic leadership, by organizing and carrying out school activities, and, service projects, and plan events that contribute for the welfare of the school and the community.  Celebra','Activity Design',43.76,'processed','2026-05-19 13:28:37','2026-05-19 13:43:30'),(2,28,'OFFICE OF STUDENT AFFAIRS AND SERVICES                        UNIVERSITY OF ANTIQUE STUDENT GOVERNMENT          tlmc.uasg@antiquespride.edu.ph August 19, 2025 PORFERIO S. BANGCAYA, PhD. Campus Director University of Antique Tario-Lim Memorial Campus Tibiao,Antique  Dear Dr. Bangcaya, Greetings! The University of Antique Student Government (UASG) serves as a medium of expression for the ideals and aspirations of every student of the University, promotes, and protects student’s welfare and interest, develops their potentials, skills, and dynamic leadership by organizing and carrying out school activities, service projects, and plan events that contribute for the welfare of the school and the community. This is to inform you that the University of Antique Student Government (UASG) will be organizing an official meet and greet with Dr. Pablo S. Crespo Jr. on August 20, 2025, 9:30 A.M at Recreational Fitness Center (RFC) transpired in the zoom meeting with the University President last Au','Letter',44.11,'processed','2026-05-19 13:33:32','2026-05-19 13:43:30'),(3,30,'OFFICE OF THE STUDENT AFFAIRS AND SERVICES UNIVERSITY OF ANTIQUE STUDENT GOVERNMENT tlmc.usg@antiquespride.edu.ph ACTIVITY DESIGN Title: TO CONDUCT A STUDENT GOVERNMENT PROVINCIAL ELECTION IN THE UNIVERSITY OF ANTIQUE TARIO-LIM MEMORIAL CAMPUS Venue: At UATLMC classrooms Date: September 12, 2025 Source of Income: UASG   Rationale: On behalf of the UASG, we are honored to formally invite you to our Leadership Training with a theme. \"Empowering YoUng LeAders, Celebrating Tradition and Culture\", which will take place on April 04-05, 2025, at the Recreational Fitness Center.  This activity serves as an essential for student leaders and organizations to develop effective leadership skills, knowledge, and practices. It helps students develop strategic thinking, problem-solving, and decision-making skills, enabling them to navigate complex situations and drive organizational success. Anent to this, we would like to invite you, Honorable, to be one of our guest speakers to discussed ideas or s','Activity Design',43.53,'processed','2026-05-19 13:38:01','2026-05-19 13:43:30'),(4,31,'Title: TO CONDUCT LEADERSHIP TRAINING IN THE UNIVERSITY OF    ANTIQUE-TARIO LIM MEMORIAL CAMPUS Venue: At UATLMC RECREATIONAL FITNESS CENTER Date: April 4-5, 2025 Source of Income: UASG   Rationale: University of Antique Student Government (UASG) is recognized as the mother of all organizations that serves as the link between the university administration and the student body which strengthen its solidarity, camaraderie and promote its total development to serve the students and the community that is created to provide students the experience and training in the democratic form of government, voice for the student body, give students opportunity to develop effective and dynamic leadership, by organizing and carrying out school activities, and, service projects, and plan events that contribute for the welfare of the school and the community.  Celebrating and conducting leadership training is a valuable experience for students. Bringing such training to the university will make their aca','Activity Design',40.96,'processed','2026-05-19 13:38:13','2026-05-19 13:43:30'),(5,32,'OFFICE OF STUDENT AFFAIRS AND SERVICES                        UNIVERSITY OF ANTIQUE STUDENT GOVERNMENT          tlmc.uasg@antiquespride.edu.ph August 19, 2025 PORFERIO S. BANGCAYA, PhD. Campus Director University of Antique Tario-Lim Memorial Campus Tibiao,Antique  Dear Dr. Bangcaya, Greetings! The University of Antique Student Government (UASG) serves as a medium of expression for the ideals and aspirations of every student of the University, promotes, and protects student’s welfare and interest, develops their potentials, skills, and dynamic leadership by organizing and carrying out school activities, service projects, and plan events that contribute for the welfare of the school and the community. This is to inform you that the University of Antique Student Government (UASG) will be organizing an official meet and greet with Dr. Pablo S. Crespo Jr. on August 20, 2025, 9:30 A.M at Recreational Fitness Center (RFC) transpired in the zoom meeting with the University President last Au','Letter',44.11,'processed','2026-05-19 13:38:20','2026-05-19 13:43:30'),(6,33,'Title: TO CONDUCT LEADERSHIP TRAINING IN THE UNIVERSITY OF    ANTIQUE-TARIO LIM MEMORIAL CAMPUS Venue: At UATLMC RECREATIONAL FITNESS CENTER Date: April 4-5, 2025 Source of Income: UASG   Rationale: University of Antique Student Government (UASG) is recognized as the mother of all organizations that serves as the link between the university administration and the student body which strengthen its solidarity, camaraderie and promote its total development to serve the students and the community that is cr